// Контент фичи «Маршруты на день»: 3 готовых маршрута на город для страницы
// /city/[slug]/trip — не туристический SEO-контент, а внутренняя engagement-фича
// для пользователей, уже пришедших на сайт (чинит монетизацию пакета «Места» за 19₽).
//
// Виктория правит этот файл руками — версионируется через git, без миграций БД.
// Ключи Record — city slug как в БД/lib/cities.ts (проверено на 2026-09-07).
//
// Курсы валют, заложенные в cost_rub (сентябрь 2026, ЦБ РФ, округлено):
//   1 GEL ≈ 33 ₽ · 1 AMD ≈ 0.24 ₽ · 1 AED ≈ 23.6 ₽ · 1000 IDR ≈ 4.6 ₽ · 1 THB ≈ 2.6 ₽
//   1000 VND ≈ 3.4 ₽ · 1 TRY ≈ 1.8 ₽ · 1 EUR ≈ 100 ₽ · 1 EGP ≈ 1.8 ₽
//
// bali: маршруты сфокусированы на Чанггу (+ Петитенгет/Беравa рядом) — это главный
// хаб, где живёт и тусуется большинство релокантов; Убуд в 1–1.5 часа езды и для
// однодневного маршрута внутри одного дня логистически не подходит.
//
// Города, добавленные 2026-09-09 (курортные/туристические направления сайта,
// где формат «маршрут на день» осмыслен — в отличие от деловых городов типа
// Варшавы или Франкфурта):
//   pattaya, samui, chiang-mai — Таиланд; nha-trang, da-nang — Вьетнам;
//   antalya, alanya, istanbul — Турция; limassol — Кипр; budva — Черногория;
//   tenerife — Испания (хаб: Санта-Крус + Ла-Лагуна, соединены трамваем ~30 мин,
//   курортные городки юга острова в 1+ часе и для одного дня не годятся);
//   sharm-el-sheikh — Египет.
//
// Курсы валют для партии городов, добавленных 2026-09-10 (ЦБ РФ, округлено):
//   1 AZN ≈ 51 ₽ · 1 GBP ≈ 117 ₽ · 1 SGD ≈ 68 ₽ · 1 JPY ≈ 0.56 ₽ · 1000 KRW ≈ 64 ₽
//   1 MXN ≈ 5.1 ₽ · 1 INR ≈ 0.91 ₽ (EUR и AMD — см. курсы выше)
//
// Города, добавленные 2026-09-10 — вторая волна раскатки на весь каталог (по
// решению Виктории — не только курорты, но и деловые/нетуристические города,
// маршрут адаптирован под характер города):
//   spb, moscow, krasnodar, kaliningrad, yekaterinburg — Россия (для Москвы,
//   Краснодара и Екатеринбурга первый день сознательно построен как «исторический
//   центр + деловой квартал + вечерняя набережная», а не курортный формат);
//   goa — Индия (хаб: Анджуна/Вагатор/Ассагао, Северный Гоа — как Бали/Пхукет,
//   курортный формат); gyumri, baku — Закавказье; singapore, tokyo, seoul —
//   Азия; london, paris, milan — Европа (дорогие столицы, budget-маршрут дороже
//   стандартной ~1000 ₽ — честно дороже жить, см. summary каждого маршрута);
//   merida — Мексика (хаб: исторический центр + Пасео-де-Монтехо, сеноты в
//   1+ часе езды и для одного дня не годятся, как Убуд для Бали).
//
// Курсы валют для партии городов, добавленных 2026-09-10 (третья волна, ЦБ РФ
// на 10.09.2026, округлено; ILS и ARS у ЦБ РФ не котируются — курс с агрегаторов):
//   1 BRL ≈ 16.8 ₽ · 1 HKD ≈ 10.9 ₽ · 1 AUD ≈ 61.8 ₽ · 1000 UZS ≈ 7.2 ₽
//   1 ILS ≈ 28.5 ₽ · 1 TJS ≈ 9.25 ₽ · 1 USD ≈ 85.5 ₽ · 1 CNY ≈ 12.7 ₽
//   1000 ARS ≈ 57 ₽ (гиперинфляция — не удивляйтесь пятизначным ценникам в песо)
//   (EUR, VND, TRY — см. курсы выше)
//
// Города, добавленные 2026-09-10 — третья волна раскатки на весь каталог:
//   rio-de-janeiro, buenos-aires — Латинская Америка; hong-kong, hanoi, sanya —
//   Азия; melbourne — Австралия (Free Tram Zone в центре реально бесплатна,
//   заложена в first-day маршрут); tashkent, bukhara — Узбекистан (одни из
//   самых дешевых маршрутов в каталоге — бюджетный день дешевле 500 ₽, это
//   честно, а не ошибка); dushanbe — Таджикистан (еще дешевле Узбекистана);
//   haifa — Израиль и miami — США (дорогие города, budget-маршрут дороже
//   стандартной ~1000 ₽, как London/Paris/Milan); amsterdam, nice, bratislava —
//   Европа; fethiye — Турция (курортный формат, как Анталья/Аланья).
//
// Курсы валют для партии городов, добавленных 2026-09-11 (четвертая волна,
// ЦБ РФ на 11.09.2026, округлено): 1 AED ≈ 23,6 ₽ · 1 AUD ≈ 61,8 ₽ ·
// 1000 KZT ≈ 160 ₽ (1 KZT ≈ 0,16 ₽) · 1 EUR ≈ 99,5 ₽ · 1 JOD ≈ 120,6 ₽
// (фиксированный курс к доллару) · 1 TRY ≈ 1,77 ₽ · 1 INR ≈ 0,91 ₽ ·
// 1 THB ≈ 2,6 ₽ (см. курс выше) · 1 RSD ≈ 0,85 ₽ · 1 KGS ≈ 0,98 ₽.
//
// Города, добавленные 2026-09-11 — четвертая волна раскатки на весь каталог:
//   abu-dhabi — ОАЭ (мечеть шейха Зайда и рыбный рынок Аль-Мина — бесплатные
//   стопы, но город растянут, поэтому first-day честно включает такси между
//   районами); adelaide — Австралия (компактный центр, почти весь first-day
//   пешком, включая бесплатные Художественную галерею и Музей Южной
//   Австралии); aktau — Казахстан (курортно-нефтяной город на Каспии, самый
//   скромный по достопримечательностям в партии — маршруты честно короче и
//   проще); alicante, barcelona — Испания; almaty, astana — Казахстан
//   (столица и бывшая столица, оба города дорогие по меркам СНГ);
//   amman — Иордания (Hashem Restaurant — культовая фалафельная без вывески);
//   ankara — Турция (деловая столица без моря, маршрут не курортный);
//   athens — Греция; bangalore — Индия (визовый режим сложный, но маршруты
//   почти все в пешей/трафик-доступности); bangkok — Таиланд (продолжение
//   раскатки того же города, что уже был в каталоге); belgrade — Сербия;
//   berlin — Германия; bishkek — Киргизия.

export type RouteStop = {
  name: string;
  type:
    | "cafe"
    | "restaurant"
    | "district"
    | "market"
    | "coworking"
    | "park"
    | "attraction";
  description: string;
  duration_min: [number, number];
  cost_rub: [number, number];
  tip?: string;
  transfer?: {
    mode: "walk" | "transit" | "taxi";
    minutes: number;
    cost_rub?: number;
  };
};

export type CityRoute = {
  slug: string;
  title: string;
  theme: "first-day" | "gourmet" | "budget";
  summary: string;
  hours: [number, number];
  free: boolean;
  stops: RouteStop[];
};

